               $vat_rate_counter++;
           }
           $vat = $vat + $head->vat_amount;
           $total = $total + $head->total_amount;
        @endphp
    @endforeach

    @php
    if($vat_rate > 0 && $vat_rate_counter > 0){
        $rate = $vat_rate/$vat_rate_counter;
    }else{
         $rate = 0;
    }

